import React, { useState } from 'react';
import './Auth.css';

const Dashboard = ({ user, onLogout }) => {
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [bookingSuccess, setBookingSuccess] = useState(false);
  const [bookingDetails, setBookingDetails] = useState(null);

  const movies = [
    {
      id: 1,
      title: 'Avengers: Endgame',
      genre: 'Action',
      duration: '3h 1m',
      rating: 'PG-13',
      description: 'The epic conclusion to the Infinity Saga.',
      price: 12.99
    },
    {
      id: 2,
      title: 'The Batman',
      genre: 'Action, Crime',
      duration: '2h 56m',
      rating: 'PG-13',
      description: 'The Dark Knight of Gotham City begins his war on crime.',
      price: 11.99
    },
    {
      id: 3,
      title: 'Spider-Man: No Way Home',
      genre: 'Action, Adventure',
      duration: '2h 28m',
      rating: 'PG-13',
      description: 'Spider-Man seeks the help of Doctor Strange when his secret identity is revealed.',
      price: 13.99
    },
    {
      id: 4,
      title: 'Dune',
      genre: 'Sci-Fi',
      duration: '2h 35m',
      rating: 'PG-13',
      description: 'A noble family becomes embroiled in a war for control over the galaxy\'s most valuable asset.',
      price: 12.49
    }
  ];

  const handleBookTicket = (movie) => {
    setSelectedMovie(movie);
    setBookingSuccess(false);
    setBookingDetails(null);
  };

  const confirmBooking = () => {
    if (selectedMovie) {
      // Simulate booking process
      const booking = {
        id: Date.now(),
        movie: selectedMovie.title,
        user: user.username,
        date: new Date().toLocaleDateString(),
        time: '7:00 PM',
        seats: ['A1', 'A2'],
        total: selectedMovie.price * 2,
        bookingId: 'BK' + Date.now()
      };

      setBookingDetails(booking);
      setBookingSuccess(true);

      // Reset after 5 seconds
      setTimeout(() => {
        setSelectedMovie(null);
        setBookingSuccess(false);
      }, 5000);
    }
  };

  const cancelBooking = () => {
    setSelectedMovie(null);
    setBookingSuccess(false);
    setBookingDetails(null);
  };

  console.log('🎬 Dashboard loaded for user:', user);

  return (
